for number in numbers:
        # Step 2: % gives the remainder after the division.
        remainder = number % 2

        # Step 3: == 0 is required. A remainder of 1 is already truthy,
        # so writing "if remainder:" would be True for every odd number.
        if remainder == 0:
            print(f"{number} is Even")
        else:
            print(f"{number} is Odd")

    print("=" * 50)

for age in ages:
        # Step 2: the chained comparison 18 <= age <= 65 is the same as
        # 18 <= age and age <= 65.
        if min_age <= age <= max_age:
            print(f"{age}: In range ({min_age} to {max_age})")
        # Step 3: elif only runs when the if above was False.
        elif age < min_age:
            print(f"{age}: Too young")
        else:
            print(f"{age}: Too old")

    # The explicit version works in Python too, it is just longer.
    print("-" * 50)
    print("Same check written with 'and':")
    for age in ages:
        if age >= min_age and age <= max_age:
            print(f"{age}: In range ({min_age} to {max_age})")
        elif age < min_age:
            print(f"{age}: Too young")
        else:
            print(f"{age}: Too old")
    print("=" * 50)

for num in (num_1, num_2):
