for text in texts:
        # Step 1: fresh stack for every text, so the runs do not mix up.
        stack = []
        balanced = True
        print(f"Text: {text}")

        # Step 2 and 3: push on "(", pop on ")".
        for character in text:
            if character == "(":
                stack.append(character)
            else:
                # The guard: a ")" with nothing to close is already broken.
                if stack:
                    stack.pop()
                else:
                    balanced = False

        # Step 4: the if/else ladder that decides the final word.
        if balanced:
            if stack:
                result = "Not balanced"
            else:
                result = "Balanced"
        else:
            result = "Not balanced"

        print(f"{text} -> {result}, leftover on the stack: {stack}")
        print("-" * 50)

for item in items:
        # Count every item we actually looked at, so the break is visible.
        checked = checked + 1
        if item.lower() == search.lower():
            found = True
            break

    print("Items: " + str(items))
    print("Searching for: " + search)
    print("Items checked before the match: " + str(checked))

    if found:
        print("Found")
    else:
        print("Not found")

for number in items:
        if number % 2 == 0:
            even.append(number)
        else:
            dropped.append(number)

    print("Original: " + str(items))
    print("Dropped as odd: " + str(dropped))
    print("Kept as even: " + str(even))
    print("Original after: " + str(items))

